\"Coerce a CLI string value to the correct type based on field spec.\"\"\"\n50\t    field_type = field_spec.get(\"type\", \"string\")\n51\t\n52\t    # null/none clears a field regardless of its type. Previously only string\n53\t    # and list accepted it: `gated_by=null` on a dict field reached the schema\n54\t    # as the string \"null\" (\"expected dict, got str\") and int fields crashed\n55\t    # in int() — both hit by revise agents in the 2026-08-19 eval run, one of\n56\t    # which resorted to editing this script mid-run to proceed.\n57\t    if value_str.lower() in (\"null\", \"none\"):\n58\t        return None\n59\t\n60\t    if field_type == \"bool\":\n61\t        if value_str.lower() in (\"true\", \"1\", \"yes\"):\n62\t            return True\n63\t        if value_str.lower() in (\"false\", \"0\", \"no\"):\n64\t            return False\n65\t        raise ValueError(f\"Cannot convert '{value_str}' to bool\")\n66\t\n67\t    if field_type == \"int\":\n68\t        try:\n69\t            return int(value_str)\n70\t        except ValueError:\n71\t            raise ValueError(\n72\t                f\"Cannot convert '{value_str}' to int (use 'null' to clear)\")\n73\t\n74\t    if field_type == \"list\":\n75\t        if value_str.startswith(\"[\"):\n76\t            import json\n77\t            try:\n78\t                return json.loads(value_str)\n79\t            except json.JSONDecodeError:\n80\t                # Agents commonly write [A-1,B-2] without quotes, which is not\n81\t                # JSON. Fall back to comma-splitting the bracket contents\n82\t                # instead of failing the whole set command.\n83\t                inner = value_str.strip()[1:-1] if value_str.strip().endswith(\"]\") \\\n84\t                    else value_str.strip()[1:]\n85\t                return [v.strip().strip(\"'\\\"\") for v in inner.split(\",\") if v.strip()]\n86\t        return [v.strip() for v in value_str.split(\",\") if v.strip()]\n87\t\n88\t    if field_type == \"dict\":\n89\t        import json\n90\t        try:\n91\t            parsed = json.loads(value_str)\n92\t        except json.JSONDecodeError:\n93\t            raise ValueError(\n94\t                f\"Cannot convert '{value_str}' to dict: pass a JSON object \"\n95\t                f\"(e.g. '{{\\\"action\\\": \\\"rewrite\\\"}}'), 'null' to clear, or set \"\n96\t                f\"nested fields individually with parent.child=value\")\n97\t        if not isinstance(parsed, dict):\n98\t            raise ValueError(f\"Expected a JSON object for dict field, got \"\n99\t                             f\"{type(parsed).__name__}\")\n100\t        return parsed\n101\t\n102\t    if field_type == \"string\":\n103\t        return value_str\n104\t\n105\t    return value_str\n106\t\n107\t\n108\tdef _detect_schema_type(path):\n109\t    \"\"\"Detect schema type from file path.\"\"\"\n110\t    basename = os.path.basename(path)\n111\t\n112\t    if \"/epic-reviews/\" in path or path.startswith(\"epic-reviews/\"):\n113\t        return \"decomp-review\"\n114\t    if \"/epic-tasks/\" in path or path.startswith(\"epic-tasks/\"):\n115\t        if basename.endswith(\"-decomposition.md\"):\n116\t            return \"decomp-summary\"\n117\t        return \"epic-task\"\n118\t    if \"/strat-tasks/\" in path or path.startswith(\"strat-tasks/\"):\n119\t        return \"strat-task\"\n120\t    return None\n121\t\n122\t\n123\tdef cmd_schema(args):\n124\t    \"\"\"Print the schema for a file type.\"\"\"\n125\t    try:\n126\t        yaml_str = get_schema_yaml(args.schema_type)\n127\t        print(yaml_str)\n128\t    except ValueError as e:\n129\t        print(f\"Error: {e}\", file=sys.stderr)\n130\t        sys.exit(1)\n131\t\n132\t\n133\tdef cmd_read(args):\n134\t    \"\"\"Read and display frontmatter from a file.\"\"\"\n135\t    if not os.path.exists(args.file):\n136\t        print(f\"Error: {args.file} not found\", file=sys.stderr)\n137\t        sys.exit(1)\n138\t\n139\t    schema_type = args.schema_type or _detect_schema_type(args.file)\n140\t\n141\t    if schema_type:\n142\t        try:\n143\t            data, _ = read_frontmatter_validated(args.file, schema_type)\n144\t        except ValidationError as e:\n145\t            print(f\"Error: {e}\", file=sys.stderr)\n146\t            sys.exit(1)\n147\t    else:\n148\t        data, _ = read_frontmatter(args.file)\n149\t        if not data:\n150\t            print(f\"Error: no frontmatter found in {args.file}\",\n151\t                  file=sys.stderr)\n152\t            sys.exit(1)\n153\t\n154\t    json.dump(data, sys.stdout, indent=2, default=str)\n155\t    print()\n156\t\n157\t\n158\tdef cmd_set(args):\n159\t    \"\"\"Set/update frontmatter fields on a file.\"\"\"\n160\t    schema_type = args.schema_type or _detect_schema_type(args.file)"}]},"parent_tool_use_id":"chatcmpl-tool-99f844a42ff9bb63","agent_id":"af98b122f29171fcb","session_id":"66891df0-ced6-412e-9fab-8ee1943bcf3f","uuid":"17dd506a-bbb2-4e16-b1e4-65990c2bd9f9","timestamp":"2026-10-26T21:21:11.299Z","tool_result_meta":[{"id":"chatcmpl-tool-a1ed7eae7c38f865","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}],"subagent_type":"general-purpose","task_description":"Decompose RHAISTRAT-9016"}
